  <main>
    <section class="page" id="gamePage">
      <h1>2048 Game</h1>
      <div class="controls">
        <div class="scores">
          <div class="scorebox"><small>SCORE</small><strong id="score">20</strong></div>
          <div class="scorebox"><small>BEST</small><strong id="best">20</strong></div>
        </div>
        <button class="btn newgame" id="newGame">New game</button>
      </div>

      <div class="board" id="board" aria-label="2048 board"></div>

      <div class="ad-wrap">
        <img src="__PLACEHOLDER_ASSETS_BASE_DIR__/015.png" width="300" height="250" alt="Advertisement">
      </div>
    </section>

    <section class="instructions">
      <p>
        Use your arrow keys (also W, A, S, and D keys alternatively) or swipe with your fingers to move the tiles.
        For example, if you joined 2 tiles with the number 2, they will become 4, 2 tiles with 4 will become 8,
        and so on. The point of the game is to get the 2048 tile!
      </p>
    </section>

    <section class="other">
      <h2>Play Other Games</h2>
      <div class="game-strip">
        <div class="strip-item"></div>
        <div class="strip-item"></div>
        <div class="strip-item"></div>
        <div class="strip-item"></div>
      </div>
    </section>
